#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

size_t rimuovi_newline(char s[]);
size_t conta_carattere(const char s[], char bersaglio);
bool e_palindroma(const char s[], size_t lunghezza);
void inverti_stringa(char s[], size_t lunghezza);

int main(void) {
    char testo[128];
    char riga_c[32];
    char bersaglio = '\0';
    char extra = '\0';

    if (fgets(testo, (int)sizeof(testo), stdin) == nullptr ||
        fgets(riga_c, (int)sizeof(riga_c), stdin) == nullptr ||
        sscanf(riga_c, " %c %c", &bersaglio, &extra) != 1) {
        fprintf(stderr, "Errore: input non valido.\n");
        return EXIT_FAILURE;
    }
    size_t len = rimuovi_newline(testo);
    size_t occ = conta_carattere(testo, bersaglio);
    bool pal = e_palindroma(testo, len);
    inverti_stringa(testo, len);

    printf("Lunghezza: %zu\n", len);
    printf("Occorrenze di '%c': %zu\n", bersaglio, occ);
    printf("Palindroma: %s\n", pal ? "si" : "no");
    printf("Invertita:\n");
    puts(testo);
    return EXIT_SUCCESS;
}

size_t rimuovi_newline(char s[]) {
    size_t i = 0;
    while (s[i] != '\0' && s[i] != '\n') {
        ++i;
    }
    s[i] = '\0';
    return i;
}

size_t conta_carattere(const char s[], char bersaglio) {
    size_t conteggio = 0;
    for (size_t i = 0; s[i] != '\0'; ++i) {
        if (s[i] == bersaglio) { ++conteggio; }
    }
    return conteggio;
}

bool e_palindroma(const char s[], size_t lunghezza) {
    for (size_t i = 0; i < lunghezza / 2; ++i) {
        if (s[i] != s[lunghezza - 1 - i]) { return false; }
    }
    return true;
}

void inverti_stringa(char s[], size_t lunghezza) {
    for (size_t i = 0; i < lunghezza / 2; ++i) {
        char tmp = s[i];
        s[i] = s[lunghezza - 1 - i];
        s[lunghezza - 1 - i] = tmp;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    const char AMMESSI[] = "abcdefghijklmnopqrstuvwxyz0123456789-_";
    char chiave[32], voce[48], prima_less[48] = "", ultima_less[48] = "", trovate[128] = "";
    if (fgets(chiave, (int)sizeof(chiave), stdin) == nullptr) {
        fprintf(stderr, "Errore: chiave mancante.\n");
        return EXIT_FAILURE;
    }
    chiave[strcspn(chiave, "\n")] = '\0';
    size_t len_chiave = strlen(chiave);
    if (len_chiave == 0) {
        fprintf(stderr, "Errore: chiave vuota.\n");
        return EXIT_FAILURE;
    }
    int valide = 0, scartate = 0, uguali = 0, prefissi = 0, contenute = 0, con_sep = 0;
    while (fgets(voce, (int)sizeof(voce), stdin) != nullptr) {
        voce[strcspn(voce, "\n")] = '\0';
        size_t len = strlen(voce);
        if (len == 0) { continue; }
        if (strspn(voce, AMMESSI) != len) {
            ++scartate;
            continue;
        }
        if (valide == 0) {
            strcpy(prima_less, voce);
            strcpy(ultima_less, voce);
        } else {
            if (strcmp(voce, prima_less) < 0) { strcpy(prima_less, voce); }
            if (strcmp(voce, ultima_less) > 0) { strcpy(ultima_less, voce); }
        }
        ++valide;
        if (strcmp(voce, chiave) == 0) { ++uguali; }
        if (strncmp(voce, chiave, len_chiave) == 0) { ++prefissi; }
        if (strpbrk(voce, "-_") != nullptr) { ++con_sep; }
        if (strstr(voce, chiave) != nullptr) {
            ++contenute;
            size_t cur = strlen(trovate);
            size_t sep = (cur > 0) ? 2 : 0;
            if (cur + sep + len < sizeof(trovate)) {
                if (sep > 0) { strncat(trovate, ", ", sizeof(trovate) - cur - 1); }
                strncat(trovate, voce, sizeof(trovate) - strlen(trovate) - 1);
            }
        }
    }
    if (valide == 0) {
        printf("Nessuna etichetta valida.\nValide: 0, scartate: %d\n", scartate);
        return EXIT_SUCCESS;
    }
    printf("Valide: %d, scartate: %d\n", valide, scartate);
    printf("Uguali a chiave: %d\nCon prefisso chiave: %d\n", uguali, prefissi);
    printf("Contengono chiave: %d\nCon separatore (- o _): %d\n", contenute, con_sep);
    printf("Prima lessicografica: %s\nUltima lessicografica: %s\n", prima_less, ultima_less);
    printf("Corrispondenze: %s\n", trovate[0] != '\0' ? trovate : "(nessuna)");
    return EXIT_SUCCESS;
}

#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void normalizza_testo(const char orig[], char dest[], size_t cap);
bool normalizza_colore_hex(const char orig[], char dest[], size_t cap);

int main(void) {
    char frase[128], pulita[128], colore_in[32], colore_out[8];
    if (fgets(frase, (int)sizeof(frase), stdin) == nullptr ||
        fgets(colore_in, (int)sizeof(colore_in), stdin) == nullptr) {
        fprintf(stderr, "Errore: righe mancanti in ingresso.\n");
        return EXIT_FAILURE;
    }
    frase[strcspn(frase, "\n")] = '\0';
    colore_in[strcspn(colore_in, "\n")] = '\0';

    normalizza_testo(frase, pulita, sizeof(pulita));
    int parole = 0, alnum = 0, punt = 0, stamp = 0;
    bool in_parola = false;
    for (size_t i = 0; pulita[i] != '\0'; ++i) {
        unsigned char uc = (unsigned char)pulita[i];
        if (isalnum(uc)) { ++alnum; }
        if (ispunct(uc)) { ++punt; }
        if (isprint(uc)) { ++stamp; }
        if (!isspace(uc) && !in_parola) { ++parole; in_parola = true; }
        else if (isspace(uc)) { in_parola = false; }
    }
    printf("Testo normalizzato: [%s]\n", pulita);
    printf("Parole: %d\n", parole);
    printf("Alfanumerici: %d, punteggiatura: %d, stampabili: %d\n", alnum, punt, stamp);
    if (normalizza_colore_hex(colore_in, colore_out, sizeof(colore_out))) {
        printf("Colore valido: %s\n", colore_out);
    } else {
        printf("Colore non valido\n");
    }
    return EXIT_SUCCESS;
}

void normalizza_testo(const char orig[], char dest[], size_t cap) {
    if (cap == 0) { return; }
    size_t out = 0;
    bool spazio_pendente = false;
    for (size_t i = 0; orig[i] != '\0'; ++i) {
        unsigned char uc = (unsigned char)orig[i];
        if (isspace(uc)) {
            if (out > 0) { spazio_pendente = true; }
        } else {
            if (spazio_pendente && out + 1 < cap) { dest[out++] = ' '; }
            spazio_pendente = false;
            if (out + 1 < cap) { dest[out++] = (char)tolower(uc); }
        }
    }
    dest[out] = '\0';
}

bool normalizza_colore_hex(const char orig[], char dest[], size_t cap) {
    if (cap < 8 || strlen(orig) != 7 || orig[0] != '#') { return false; }
    dest[0] = '#';
    for (size_t i = 1; i < 7; ++i) {
        unsigned char uc = (unsigned char)orig[i];
        if (!isxdigit(uc)) { return false; }
        dest[i] = (char)toupper(uc);
    }
    dest[7] = '\0';
    return true;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int formatta_record(char dest[], size_t cap, const char codice[],
                    const char titolo[], int anno, double prezzo);

int main(void) {
    char riga[128], codice[24], titolo[80], completo[128], anteprima[24];
    int anno = 0;
    double prezzo = 0.0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%23s %c", codice, &extra) != 1) {
        fprintf(stderr, "Errore: codice non valido.\n");
        return EXIT_FAILURE;
    }
    if (fgets(titolo, (int)sizeof(titolo), stdin) == nullptr) {
        fprintf(stderr, "Errore: titolo mancante.\n");
        return EXIT_FAILURE;
    }
    titolo[strcspn(titolo, "\n")] = '\0';
    if (titolo[0] == '\0') {
        fprintf(stderr, "Errore: titolo vuoto.\n");
        return EXIT_FAILURE;
    }
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %lf %c", &anno, &prezzo, &extra) != 2 ||
        anno < 1900 || anno > 2100 || prezzo < 0.0) {
        fprintf(stderr, "Errore: anno o prezzo non validi.\n");
        return EXIT_FAILURE;
    }

    int req = snprintf(nullptr, 0, "%s;%s;%d;%.2f", codice, titolo, anno, prezzo);
    int r_comp = formatta_record(completo, sizeof(completo), codice, titolo, anno, prezzo);
    int r_ant = formatta_record(anteprima, sizeof(anteprima), codice, titolo, anno, prezzo);
    if (req < 0 || r_comp < 0 || r_ant < 0) {
        fprintf(stderr, "Errore: formattazione fallita.\n");
        return EXIT_FAILURE;
    }

    bool comp_tronc = (size_t)r_comp >= sizeof(completo);
    bool ant_tronc = (size_t)r_ant >= sizeof(anteprima);
    printf("Lunghezza richiesta: %d\n", req);
    printf("Completo (%s): %s\n", comp_tronc ? "troncato" : "ok", completo);
    printf("Anteprima (%s): %s\n", ant_tronc ? "troncato" : "ok", anteprima);
    if (ant_tronc) {
        int omessi = req - (int)(sizeof(anteprima) - 1);
        printf("Caratteri omessi in anteprima: %d\n", omessi);
    }
    return EXIT_SUCCESS;
}

int formatta_record(char dest[], size_t cap, const char codice[],
                    const char titolo[], int anno, double prezzo) {
    return snprintf(dest, cap, "%s;%s;%d;%.2f", codice, titolo, anno, prezzo);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int leggi_riga_limitata(char buf[], size_t cap);
bool accoda_voce(char dest[], size_t cap, const char voce[], const char sep[]);

int main(void) {
    char riga[16];
    char elenco[40] = "";
    int inserite = 0;
    int omesse = 0;
    int troncate = 0;

    int stato = 0;
    while ((stato = leggi_riga_limitata(riga, sizeof(riga))) != 0) {
        if (stato == 2) {
            ++troncate;
        }
        if (riga[0] == '\0') {
            continue;
        }
        if (accoda_voce(elenco, sizeof(elenco), riga, " | ")) {
            ++inserite;
        } else {
            ++omesse;
        }
    }

    printf("Voci inserite: %d\n", inserite);
    printf("Voci omesse per capienza: %d\n", omesse);
    printf("Righe troncate in ingresso: %d\n", troncate);
    printf("Elenco (%zu/%zu): %s\n", strlen(elenco), sizeof(elenco) - 1, elenco);
    return EXIT_SUCCESS;
}

int leggi_riga_limitata(char buf[], size_t cap) {
    if (cap == 0 || fgets(buf, (int)cap, stdin) == nullptr) {
        return 0;
    }
    size_t len = strcspn(buf, "\n");
    if (buf[len] == '\n') {
        buf[len] = '\0';
        return 1;
    }
    int c = getchar();
    if (c == '\n' || c == EOF) {
        return 1;
    }
    while (c != '\n' && c != EOF) {
        c = getchar();
    }
    return 2;
}

bool accoda_voce(char dest[], size_t cap, const char voce[], const char sep[]) {
    size_t len_dest = strlen(dest);
    size_t len_sep = (len_dest > 0) ? strlen(sep) : 0;
    size_t len_voce = strlen(voce);
    if (len_dest + len_sep + len_voce >= cap) {
        return false;
    }
    if (len_sep > 0) {
        strcat(dest, sep);
    }
    strcat(dest, voce);
    return true;
}
